import { z } from "zod";
import { DisplayName, EpochMs, Id, Port } from "../common.js";

/**
 * MySQL/MariaDB database hosts and per-server databases (Pterodactyl "Databases").
 *
 * Administrators (`database_hosts.manage`) register database hosts with an admin account the control plane
 * uses to create databases and users. Server users then create databases on a host
 * (`servers.databases.create`), each with its own MySQL account that is granted privileges on that one
 * database only. Passwords are generated by the control plane, stored encrypted and only returned by the
 * separate password route (`servers.databases.view_password`). The host admin password is write-only.
 *
 * Names: database `s<shortId>_<name>` (≤ 58 chars, within MySQL's 64-character identifier limit),
 * username `u<shortId>_<10 random [a-z0-9]>` (20 chars, within MySQL 5.7+/MariaDB's 32-character limit).
 */

/**
 * TLS towards the database host (named after the MySQL client's SSL modes):
 * - `disabled`: plain TCP.
 * - `preferred`: encrypted when the server offers TLS, plain otherwise; the certificate is NOT verified.
 * - `required`: encrypted or fail, but the certificate is NOT verified (protects against passive sniffing
 *   only; an active man-in-the-middle can impersonate the host).
 * - `verify_ca`: encrypted, and the server certificate must chain to `tlsCaCertificate` (required for this
 *   mode and accepted only with it); the host name is not checked (MySQL `VERIFY_CA`).
 */
export const DatabaseTlsMode = z.enum(["disabled", "preferred", "required", "verify_ca"]);
export type DatabaseTlsMode = z.infer<typeof DatabaseTlsMode>;

/** Modes that authenticate the host by its certificate (only `verify_ca`). */
export const tlsModeVerifies = (mode: DatabaseTlsMode): boolean => mode === "verify_ca";

const CA_RULE_REQUIRED = "verify_ca needs the CA certificate to verify against";
const CA_RULE_UNUSED = "A CA certificate is only used with verify_ca";
/** `tlsCaCertificate` is required with `verify_ca` and refused with every other mode. */
function checkCaRule(v: { tlsMode: DatabaseTlsMode; tlsCaCertificate: string | null }, ctx: z.RefinementCtx): void {
  if (v.tlsMode === "verify_ca" && !v.tlsCaCertificate) ctx.addIssue({ code: "custom", path: ["tlsCaCertificate"], message: CA_RULE_REQUIRED });
  if (v.tlsMode !== "verify_ca" && v.tlsCaCertificate) ctx.addIssue({ code: "custom", path: ["tlsCaCertificate"], message: CA_RULE_UNUSED });
}

const HOSTNAME_RE = /^(?=.{1,253}$)[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?(?:\.[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?)*$/;
const IPV4_RE = /^(?:25[0-5]|2[0-4]\d|1\d\d|[1-9]?\d)(?:\.(?:25[0-5]|2[0-4]\d|1\d\d|[1-9]?\d)){3}$/;
/** Plain IPv6 literal (hex groups, at most one `::`; no zone id or embedded IPv4). */
function isIpv6(input: string): boolean {
  const v = input.toLowerCase();
  if (!/^[0-9a-f:]+$/.test(v) || !v.includes(":")) return false;
  const groups = v.split(":");
  if (groups.length < 3 || groups.length > 8 || groups.some((g) => g.length > 4)) return false;
  const doubles = v.split("::").length - 1;
  if (doubles > 1 || (doubles === 0 && groups.length !== 8)) return false;
  // A single leading/trailing colon is only valid as part of `::`.
  if ((v.startsWith(":") && !v.startsWith("::")) || (v.endsWith(":") && !v.endsWith("::"))) return false;
  return true;
}

/** Host name or IP literal (no scheme, port, path or socket). */
export const DatabaseHostAddress = z
  .string()
  .trim()
  .min(1)
  .max(253)
  .refine((v) => HOSTNAME_RE.test(v) || IPV4_RE.test(v) || isIpv6(v), "Enter a host name or IP address (no port or scheme)");

/** The host's admin account name (passed to the driver, never into SQL). */
export const DatabaseAdminUsername = z
  .string()
  .min(1)
  .max(80)
  .refine((v) => [...v].every((c) => c.charCodeAt(0) > 0x1f && c.charCodeAt(0) !== 0x7f), "Control characters are not allowed");

/** Write-only admin password. */
export const DatabaseAdminPassword = z.string().min(1).max(256);

/** PEM CA certificate(s) pinned for `tlsMode` verification (public data, returned to administrators). */
export const PemCertificate = z
  .string()
  .trim()
  .max(16_384)
  .regex(/^-----BEGIN CERTIFICATE-----[\s\S]+-----END CERTIFICATE-----$/, "Paste a PEM certificate (-----BEGIN CERTIFICATE----- …)");

/** `GET /database-hosts` item. Strict: a response carrying a password (or anything else) is rejected. */
export const DatabaseHost = z
  .object({
    id: Id,
    name: z.string(),
    /** Address the control plane connects to. */
    host: z.string(),
    port: Port,
    /** Address shown to server users in connection details; null = `host`. */
    publicHost: z.string().nullable(),
    username: z.string(),
    /** Servers on this node prefer this host when it has capacity. */
    nodeId: Id.nullable(),
    nodeName: z.string().nullable(),
    /** null = unlimited. */
    maxDatabases: z.number().int().nonnegative().nullable(),
    databaseCount: z.number().int().nonnegative(),
    tlsMode: DatabaseTlsMode,
    tlsCaCertificate: z.string().nullable(),
    notes: z.string(),
    createdAt: EpochMs,
    updatedAt: EpochMs,
  })
  .strict();
export type DatabaseHost = z.infer<typeof DatabaseHost>;

export const CreateDatabaseHostRequest = z
  .object({
    name: DisplayName,
    host: DatabaseHostAddress,
    port: Port.default(3306),
    publicHost: DatabaseHostAddress.nullable().default(null),
    username: DatabaseAdminUsername,
    /** Write-only; never returned, logged or audited. */
    password: DatabaseAdminPassword,
    nodeId: Id.nullable().default(null),
    maxDatabases: z.number().int().min(0).max(100_000).nullable().default(null),
    tlsMode: DatabaseTlsMode.default("preferred"),
    /** Only with (and required by) `tlsMode: "verify_ca"`. */
    tlsCaCertificate: PemCertificate.nullable().default(null),
    notes: z.string().max(1024).default(""),
  })
  .strict()
  .superRefine(checkCaRule);
export type CreateDatabaseHostRequest = z.infer<typeof CreateDatabaseHostRequest>;

/**
 * `PATCH /database-hosts/:id`: omitted fields are kept; an omitted `password` keeps the stored one. The CA
 * rule applies to the resulting host: switching away from `verify_ca` clears the stored CA, switching to it
 * needs one, and sending a CA with another mode is refused (400).
 */
export const UpdateDatabaseHostRequest = z
  .object({
    name: DisplayName.optional(),
    host: DatabaseHostAddress.optional(),
    port: Port.optional(),
    publicHost: DatabaseHostAddress.nullable().optional(),
    username: DatabaseAdminUsername.optional(),
    password: DatabaseAdminPassword.optional(),
    nodeId: Id.nullable().optional(),
    maxDatabases: z.number().int().min(0).max(100_000).nullable().optional(),
    tlsMode: DatabaseTlsMode.optional(),
    tlsCaCertificate: PemCertificate.nullable().optional(),
    notes: z.string().max(1024).optional(),
  })
  .strict();
export type UpdateDatabaseHostRequest = z.infer<typeof UpdateDatabaseHostRequest>;

/**
 * `POST /database-hosts/test`: tests connection settings before they are saved. Without `password`,
 * `hostId` names the saved host whose stored password is used (testing an edit form).
 */
export const TestDatabaseHostRequest = z
  .object({
    host: DatabaseHostAddress,
    port: Port.default(3306),
    username: DatabaseAdminUsername,
    password: DatabaseAdminPassword.optional(),
    tlsMode: DatabaseTlsMode.default("preferred"),
    tlsCaCertificate: PemCertificate.nullable().default(null),
    hostId: Id.optional(),
  })
  .strict()
  .refine((v) => v.password !== undefined || v.hostId !== undefined, { path: ["password"], message: "Enter the password" })
  .superRefine(checkCaRule);
export type TestDatabaseHostRequest = z.infer<typeof TestDatabaseHostRequest>;

export const DatabaseHostTestResult = z.object({
  ok: z.boolean(),
  /** Short, credential-free reason when `ok` is false. */
  error: z.string().nullable(),
  serverVersion: z.string().nullable(),
  /** Whether the session was encrypted (not whether the host was authenticated — see `DatabaseTlsMode`). */
  tls: z.boolean().nullable(),
  latencyMs: z.number().int().nonnegative().nullable(),
});
export type DatabaseHostTestResult = z.infer<typeof DatabaseHostTestResult>;

// ---------------------------------------------------------------------------------------------
// Per-server databases

/** Longest user-chosen database name part (`s<8 hex>_` + 48 = 58 ≤ 64). */
export const SERVER_DATABASE_NAME_MAX = 48;
/** Random part of generated usernames (`u<8 hex>_` + 10 = 20 ≤ 32). */
export const SERVER_DATABASE_USERNAME_RANDOM_LENGTH = 10;

/** User-chosen part of a database name: lowercase letters, digits and underscores. */
export const ServerDatabaseName = z
  .string()
  .regex(/^[a-z0-9_]{1,48}$/, "Use 1–48 lowercase letters, digits or underscores");

/** Full MySQL database name of a server database. */
export const serverDatabaseFullName = (serverShortId: string, name: string): string => `s${serverShortId}_${name}`;

const OCTET = /^(?:25[0-5]|2[0-4]\d|1\d\d|[1-9]?\d)$/;
const ipv4Int = (s: string): number | null => {
  const parts = s.split(".");
  if (parts.length !== 4 || !parts.every((p) => OCTET.test(p))) return null;
  return parts.reduce((acc, p) => acc * 256 + Number(p), 0);
};
const intIpv4 = (n: number): string => [24, 16, 8, 0].map((s) => Math.floor(n / 2 ** s) % 256).join(".");
const contiguousPrefix = (mask: number): number | null => {
  for (let bits = 1; bits <= 32; bits++) if (mask === 2 ** 32 - 2 ** (32 - bits)) return bits;
  return null;
};
const DNS_LABEL = /^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$/;

/** Longest accepted "connections from" pattern (MySQL < 8.0.17 limits the host part to 60). */
export const DATABASE_REMOTE_MAX = 60;

/**
 * Validates and normalises a MySQL account host pattern ("connections from"). Accepted forms:
 * `%` (anywhere); an IPv4 address; an IPv4 prefix wildcard (`10.%`, `192.168.1.%`); IPv4 CIDR
 * (`10.0.0.0/8`, rewritten to MySQL/MariaDB's portable netmask form `10.0.0.0/255.0.0.0`); IPv4
 * address/netmask with a contiguous mask; a host name, optionally with a leading `%.` wildcard
 * (`%.example.com`, lowercased); an IPv6 address (lowercased). Host bits under the mask must be zero.
 * Returns null when invalid. The result only contains `[a-z0-9.%:/-]`.
 */
export function normalizeDatabaseRemote(input: string): string | null {
  const v = input.trim().toLowerCase();
  if (v.length === 0 || v.length > DATABASE_REMOTE_MAX) return null;
  if (v === "%") return v;
  if (ipv4Int(v) !== null) return v;
  const wildcard = /^((?:\d{1,3}\.){1,3})%$/.exec(v);
  if (wildcard) {
    const octets = wildcard[1]!.slice(0, -1).split(".");
    return octets.every((o) => OCTET.test(o)) ? v : null;
  }
  const slash = v.indexOf("/");
  if (slash > 0) {
    const ip = ipv4Int(v.slice(0, slash));
    const maskPart = v.slice(slash + 1);
    if (ip === null) return null;
    let bits: number | null;
    if (/^\d{1,2}$/.test(maskPart)) {
      bits = Number(maskPart);
    } else {
      const mask = ipv4Int(maskPart);
      bits = mask === null ? null : contiguousPrefix(mask);
    }
    if (bits === null || bits < 1 || bits > 32) return null;
    // Host bits must be zero (MySQL matches `client_ip & netmask == host_ip`); arithmetic, not 32-bit ops.
    if (ip % 2 ** (32 - bits) !== 0) return null;
    const out = `${intIpv4(ip)}/${intIpv4(2 ** 32 - 2 ** (32 - bits))}`;
    return out.length <= DATABASE_REMOTE_MAX ? out : null;
  }
  if (v.includes(":")) return isIpv6(v) ? v : null;
  const labels = v.startsWith("%.") ? v.slice(2).split(".") : v.split(".");
  if (!labels.length || !labels.every((l) => DNS_LABEL.test(l))) return null;
  // A bare all-numeric dotted name would be a mistyped IP address.
  if (labels.every((l) => /^\d+$/.test(l))) return null;
  return v;
}

/** "Connections from" (MySQL account host part), normalised by {@link normalizeDatabaseRemote}. */
export const DatabaseRemote = z
  .string()
  .max(255)
  .refine((v) => normalizeDatabaseRemote(v) !== null, "Use %, an IPv4 address, a wildcard like 10.0.%, a CIDR like 10.0.0.0/8, or a host name")
  .transform((v) => normalizeDatabaseRemote(v) as string);

export const ServerDatabase = z
  .object({
    id: Id,
    serverId: Id,
    hostId: Id,
    hostName: z.string(),
    /** Address users connect to (the host's `publicHost`, else its `host`). */
    host: z.string(),
    port: Port,
    /** Full MySQL database name (`s<shortId>_<name>`). */
    database: z.string(),
    username: z.string(),
    /** MySQL account host pattern ("connections from"). */
    remote: z.string(),
    createdAt: EpochMs,
    passwordRotatedAt: EpochMs.nullable(),
  })
  .strict();
export type ServerDatabase = z.infer<typeof ServerDatabase>;

export const CreateServerDatabaseRequest = z
  .object({
    name: ServerDatabaseName,
    remote: DatabaseRemote.default("%"),
    /** Pick the host explicitly (requires `database_hosts.manage`); default: automatic selection. */
    hostId: Id.optional(),
  })
  .strict();
export type CreateServerDatabaseRequest = z.input<typeof CreateServerDatabaseRequest>;

/** `GET /servers/:id/databases/:databaseId/password` (`servers.databases.view_password`, `Cache-Control: no-store`). */
export const ServerDatabasePassword = z.object({ password: z.string() }).strict();
export type ServerDatabasePassword = z.infer<typeof ServerDatabasePassword>;

/**
 * `details` of database errors: `disabled` (403, the server's `databaseLimit` is 0), `limit_reached` (409),
 * `name_taken` (409), `host_full` (409, an explicitly picked host is at `maxDatabases`), `no_host` (422 —
 * no host with capacity), `has_databases` (409, deleting a host that still has databases),
 * `host_error` (502, the database host refused or could not be reached; `code` = driver/MySQL error code),
 * `busy` (409, another create/rotate/delete of the same database is still talking to the host).
 */
export const DatabaseErrorReason = z.enum(["disabled", "limit_reached", "name_taken", "host_full", "no_host", "has_databases", "host_error", "busy"]);
export const DatabaseErrorDetails = z.object({
  reason: DatabaseErrorReason,
  limit: z.number().int().nonnegative().optional(),
  count: z.number().int().nonnegative().optional(),
  code: z.string().nullable().optional(),
});
export type DatabaseErrorDetails = z.infer<typeof DatabaseErrorDetails>;
